using System;using System.IO;using P3.Validation;using UnityEngine;
public static class P3ArtCaptureTicketSmokeTest{public static void Run(){var run="art_ticket_"+Guid.NewGuid().ToString("N");var t=ArtCaptureTicketStore.Prepare(run,"art_focus","workshop_main",ArtCaptureRole.Final,null);if(t.CaptureSource!="game_view"||t.Camera!=null||!t.ExpectedAbsolutePath.StartsWith(EvidencePaths.ForArtRun(run).Root))throw new Exception("unsafe ticket");bool rejected=false;try{ArtCaptureTicketStore.Load(run,"../raw");}catch{rejected=true;}if(!rejected)throw new Exception("unsafe ticket accepted");var texture=new Texture2D(1920,1080);File.WriteAllBytes(t.ExpectedAbsolutePath,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);var artifact=ArtEvidenceService.Finalize(run,t.TicketId);if(!File.Exists(artifact.Path)||Directory.Exists(Path.GetDirectoryName(t.ExpectedAbsolutePath)))throw new Exception("capture staging not finalized cleanly");Debug.Log("P3 Art Capture Ticket PASSED");}}
